export const strokes=[{name:'进气',color:'#63c5e5',valves:'进气门开 · 排气门关',desc:'活塞由上止点向下止点运动，进气道中的新鲜充量进入气缸。PFI 汽油机吸入空气与汽油形成的混合气。'},{name:'压缩',color:'#ba9be1',valves:'进、排气门均关闭',desc:'活塞由下止点向上止点运动，混合气被压缩，温度、压力升高。实际汽油机通常在压缩上止点前点火。'},{name:'做功',color:'#efa362',valves:'进、排气门均关闭',desc:'燃烧使缸内气体温度和压力升高，推动活塞下行，经连杆带动曲轴输出转矩。燃烧具有有限持续期，并非瞬时完成。'},{name:'排气',color:'#a7b6bf',valves:'进气门关 · 排气门开',desc:'活塞由下止点向上止点运动，废气排出。实际发动机排气门提前开启，换气上止点附近可能存在气门重叠。'}];
